-- Shared city catalog for all services.
-- This script is idempotent and can be re-run safely.

CREATE TABLE IF NOT EXISTS cities (
    id UUID PRIMARY KEY,
    country_code VARCHAR(2) NOT NULL REFERENCES countries(code),
    region_id UUID REFERENCES regions(id),
    name VARCHAR NOT NULL,
    normalized_name VARCHAR NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    UNIQUE (country_code, region_id, normalized_name)
);

DELETE FROM cities
WHERE country_code NOT IN (
    'AL','AD','AT','BY','BE','BA','BG','HR','CY','CZ','DK','EE','FI','FR','DE','GR','HU','IS','IE',
    'IT','LV','LI','LT','LU','MT','MD','MC','ME','NL','MK','NO','PL','PT','RO','RU','SM','RS','SK',
    'SI','ES','SE','CH','UA','GB','VA'
);

ON CONFLICT (id) DO UPDATE
SET
    country_code = EXCLUDED.country_code,
    region_id = EXCLUDED.region_id,
    name = EXCLUDED.name,
    normalized_name = EXCLUDED.normalized_name,
    updated_at = NOW();
